20	MemCoalescer::MemCoalescer(
21	  const SimContext& ctx,
22	  const char* name,
23	  uint32_t input_size,
24	  uint32_t output_size,
25	  uint32_t line_size,
26	  uint32_t queue_size,
27	  uint32_t delay
28	) : SimObject<MemCoalescer>(ctx, name)
29	  , ReqIn(this)
30	  , RspOut(this)
31	  , ReqOut(output_size, this)
32	  , RspIn(output_size, this)
33	  , input_size_(input_size)
34	  , output_size_(output_size)
35	  , output_ratio_(input_size / output_size)
36	  , pending_rd_reqs_(queue_size)
37	  , sent_mask_(input_size)
38	  , line_size_(line_size)
39	  , delay_(delay)
40	{}
41	
42	void MemCoalescer::on_reset() {
43	  sent_mask_.reset();
44	  out_round_.valid = false;
45	  out_round_.lanes.reset();
46	  out_round_.reqs.clear();
47	}
48	
49	void MemCoalescer::on_tick() {
50	  // process outgoing responses: merge same-tag fragments arriving across
51	  // channels this tick into one uncoalesced response.
52	  for (uint32_t o = 0; o < output_size_; ++o) {
53	    if (RspIn.at(o).empty()) {
54	      continue;
55	    }
56	    if (RspOut.full()) {
57	      break;
58	    }
59	    auto rsp0 = RspIn.at(o).peek();
60	    auto& entry = pending_rd_reqs_.at(rsp0.tag);
61	
62	    BitVector<> lane_mask(output_size_);
63	    std::vector<std::shared_ptr<mem_block_t>> lane_data(output_size_);
64	    for (uint32_t j = o; j < output_size_; ++j) {
65	      if (RspIn.at(j).empty()) {
66	        continue;
67	      }
68	      auto& r = RspIn.at(j).peek();
69	      if (r.tag != rsp0.tag) {
70	        continue;
71	      }
72	      lane_mask.set(j);
73	      lane_data.at(j) = r.data;
74	    }
75	
76	    BitVector<> rsp_mask(input_size_);
77	    for (uint32_t j = 0; j < output_size_; ++j) {
78	      if (!lane_mask.test(j)) {
79	        continue;
80	      }
81	      for (uint32_t r = 0; r < output_ratio_; ++r) {
82	        uint32_t i = j * output_ratio_ + r;
83	        if (entry.mask.test(i)) {
84	          rsp_mask.set(i);
85	        }
86	      }
87	    }
88	
89	    // build memory response — replicate each output-lane data block to all
90	    // coalesced input lanes (shared_ptr aliasing, no copy)
91	    LsuRsp out_rsp(input_size_);
92	    out_rsp.mask = rsp_mask;
93	    out_rsp.tag = entry.tag;
94	    out_rsp.cid = rsp0.hart_id;
95	    out_rsp.uuid = rsp0.uuid;
96	    for (uint32_t j = 0; j < output_size_; ++j) {
97	      if (!lane_mask.test(j)) {
98	        continue;
99	      }
100	      for (uint32_t r = 0; r < output_ratio_; ++r) {
101	        uint32_t i = j * output_ratio_ + r;
102	        if (entry.mask.test(i)) {
103	          out_rsp.data.at(i) = lane_data.at(j);
104	        }
105	      }
106	    }
107	
108	    // send memory response
109	    RspOut.send(out_rsp, 1);
110	    DT(4, this->name() << " mem-rsp: " << out_rsp);
111	
112	    // track remaining responses
113	    assert(!entry.mask.none());
114	    entry.mask &= ~rsp_mask;
115	    if (entry.mask.none()) {
116	      // whole response received, release tag
117	      pending_rd_reqs_.release(rsp0.tag);
118	    }
119	    for (uint32_t j = 0; j < output_size_; ++j) {
120	      if (lane_mask.test(j)) {
121	        RspIn.at(j).pop();
122	      }
123	    }
124	    break; // one merged response per tick
125	  }
126	
127	  // drain a pending coalesced round before building a new one
128	  if (out_round_.valid) {
129	    this->flush_out_round();
130	    return;
131	  }
132	
133	  // process incoming requests
134	  if (ReqIn.empty())
135	    return;
136	
137	  auto& in_req = ReqIn.peek();
138	  assert(in_req.mask.size() == input_size_);
139	  assert(!in_req.mask.none());
140	
141	  // ensure we can allocate a response tag
142	  if (pending_rd_reqs_.full()) {
143	    DT(4, this->name() << " queue-full: " << in_req);
144	    return;
145	  }
146	
147	  uint64_t addr_mask = ~uint64_t(line_size_-1);
148	
149	  const bool in_is_amo = in_req.is_amo();
150	
151	  BitVector<> out_mask(output_size_);
152	  std::vector<uint64_t> out_addrs(output_size_);
153	  std::vector<std::shared_ptr<mem_block_t>> out_data(output_size_);
154	  std::vector<uint64_t> out_byteen(output_size_, 0);
155	  std::vector<uint32_t> out_tids(output_size_, 0);
156	
157	  BitVector<> cur_mask(input_size_);
158	
159	  for (uint32_t o = 0; o < output_size_; ++o) {
160	    for (uint32_t r = 0; r < output_ratio_; ++r) {
161	      uint32_t i = o * output_ratio_ + r;
162	      if (sent_mask_.test(i) || !in_req.mask.test(i))
163	        continue;
164	
165	      uint64_t seed_addr = in_req.addrs.at(i) & addr_mask;
166	      cur_mask.set(i);
167	
168	      // RVA gives no commutativity guarantee across AMO operands —
169	      // do not coalesce AMO lanes that share a line; each AMO lane
170	      // emits its own request. For non-AMO, matching addresses coalesce.
171	      if (!in_is_amo) {
172	        for (uint32_t s = r + 1; s < output_ratio_; ++s) {
173	          uint32_t j = o * output_ratio_ + s;
174	          if (sent_mask_.test(j) || !in_req.mask.test(j))
175	            continue;
176	          uint64_t match_addr = in_req.addrs.at(j) & addr_mask;
177	          if (match_addr == seed_addr) {
178	            cur_mask.set(j);
179	          }
180	        }
181	      }
182	
183	      if (in_is_amo) {
184	        // Carry this lane's original tid through the output slot so the
185	        // hart id at the memory boundary names the requesting lane.
186	        // No coalescing across lanes for AMO.
187	        if (i < in_req.tids.size()) {
188	          out_tids.at(o) = in_req.tids.at(i);
189	        }
190	      }
191	
192	      // For writes and AMOs, merge per-lane data + byteen into the coalesced
193	      // block. AMOs never coalesce across lanes (cur_mask only covers lane i),
194	      // so the merge collapses to a single lane's payload.
195	      if (in_req.is_write() || in_is_amo) {
196	        std::shared_ptr<mem_block_t> merged;
197	        uint64_t merged_byteen = 0;
198	        for (uint32_t s = r; s < output_ratio_; ++s) {
199	          uint32_t j = o * output_ratio_ + s;
200	          if (!cur_mask.test(j) || !in_req.data.at(j))
201	            continue;
202	          if (!merged) {
203	            merged = make_mem_block();
204	            std::memset(merged->data(), 0, merged->size());
205	          }
206	          uint64_t lane_be = in_req.byteen.at(j);
207	          for (uint32_t b = 0; b < VX_CFG_MEM_BLOCK_SIZE; ++b) {
208	            if (lane_be & (1ull << b)) {
209	              (*merged)[b] = (*in_req.data.at(j))[b];
210	            }
211	          }
212	          merged_byteen |= lane_be;
213	        }
214	        out_data.at(o) = merged;
215	        out_byteen.at(o) = merged_byteen;
216	      }
217	
218	      out_mask.set(o);
219	      // AMOs need the byte-level address downstream so the bank can
220	      // place the RMW result at the correct offset within the line.
221	      // Non-AMO requests stay line-aligned (no semantic change).
222	      out_addrs.at(o) = in_is_amo ? in_req.addrs.at(i) : seed_addr;
223	      break;
224	    }
225	  }
226	
227	  assert(!out_mask.none());
228	
229	  uint32_t tag = 0;
230	  if (!in_req.is_write() || in_is_amo) {
231	    // Allocate a response tag for read requests and AMOs (which always
232	    // return rd). Without the AMO branch the response would route through
233	    // the write path and the LSU MSHR replay would never fire.
234	    tag = pending_rd_reqs_.allocate(pending_req_t{in_req.tag, cur_mask});
235	  }
236	
237	  // build per-channel memory requests
238	  out_round_.valid = true;
239	  out_round_.lanes = out_mask;
240	  out_round_.cur_mask = cur_mask;
241	  out_round_.reqs.assign(output_size_, MemReq{});
242	  for (uint32_t o = 0; o < output_size_; ++o) {
243	    if (!out_mask.test(o)) {
244	      continue;
245	    }
246	    auto& mr  = out_round_.reqs.at(o);
247	    mr.op     = in_req.op;
248	    mr.addr   = out_addrs.at(o);
249	    mr.data   = std::move(out_data.at(o));
250	    mr.byteen = out_byteen.at(o);
251	    mr.tag    = tag;
252	    mr.hart_id = make_hart_id(in_req.cid, in_req.wid, out_tids.at(o));
253	    mr.uuid   = in_req.uuid;
254	    mr.flags  = in_req.flags;
255	    auto t = get_addr_type(mr.addr);
256	    mr.flags.io    = (t == AddrType::IO);
257	    mr.flags.local = (t == AddrType::Shared);
258	  }
259	
260	  DT(4, this->name() << " mem-req: coalesced=" << cur_mask.count() << ", lanes=" << out_mask.count() << " (#" << in_req.uuid << ")");
261	
262	  // track partial responses
263	  perf_stats_.misses += (cur_mask.count() != in_req.mask.count());
264	
265	  // The built round is presented to the downstream on the next tick, not
266	  // this one: the coalescer alternates a build tick with a drain tick, so a
267	  // batch issues at most every other cycle. Draining is handled at the top
268	  // of on_tick when out_round_ is valid.
269	}
270	
271	// Issue the pending round's per-channel requests; commit the round once
272	// every lane has been accepted.
273	void MemCoalescer::flush_out_round() {
274	  for (uint32_t o = 0; o < output_size_; ++o) {
275	    if (!out_round_.lanes.test(o)) {
276	      continue;
277	    }
278	    if (ReqOut.at(o).try_send(out_round_.reqs.at(o), delay_)) {
279	      out_round_.lanes.reset(o);
280	    }
281	  }
282	  if (!out_round_.lanes.none()) {
283	    return;
284	  }
285	
286	  out_round_.valid = false;
287	  auto& in_req = ReqIn.peek();
288	  sent_mask_ |= out_round_.cur_mask;
289	  if (sent_mask_ == in_req.mask) {
290	    ReqIn.pop();
291	    sent_mask_.reset();
292	  }
293	}
294	
295	const MemCoalescer::PerfStats& MemCoalescer::perf_stats() const {
296	  return perf_stats_;
297	}

