1215	// Globally-unique per-hart id. Lower bits carry the most entropy
1216	// (thread, then warp, then core) so the small per-bank reservation
1217	// table sees fewer hash collisions.
1218	inline uint32_t make_hart_id(uint32_t cid, uint32_t wid, uint32_t tid) {
1219	  constexpr uint32_t LOG_WARPS   = log2ceil(VX_CFG_NUM_WARPS);
1220	  constexpr uint32_t LOG_THREADS = log2ceil(VX_CFG_NUM_THREADS);
1221	  return (cid << (LOG_WARPS + LOG_THREADS))
1222	       | (wid << LOG_THREADS)
1223	       | tid;
1224	}
